/// Set once a write to stdout has failed because its reader has gone away
/// (`api -sa seed.api | head -2`). Nothing more is written there.
static STDOUT_CLOSED: AtomicBool = AtomicBool::new(false);

/// Write all of `buf`, or flush when it is `None`. An error that only says
/// "not now" is waited out: a pipe that is full for the moment (`WouldBlock`,
/// when the other end set it non-blocking) or a call that was interrupted.
/// `write`, not `write_all`: after an error it says how much was taken.
fn write_through(to: &mut impl Write, buf: Option<&[u8]>) -> io::Result<()> {
    let mut rest = buf.unwrap_or_default();
    loop {
        let step = match buf {
            Some(_) if rest.is_empty() => return Ok(()),
            Some(_) => to.write(rest),
            None => to.flush().map(|()| 0),
        };
        match step {
            Ok(_) if buf.is_none() => return Ok(()),
            Ok(0) => return Err(io::ErrorKind::WriteZero.into()),
            Ok(n) => rest = &rest[n..],
            Err(e) if e.kind() == io::ErrorKind::Interrupted => {}
            Err(e) if e.kind() == io::ErrorKind::WouldBlock => thread::sleep(Duration::from_millis(1)),
            Err(e) => return Err(e),
        }
    }
}

/// Stdout for everything the client prints. A stdout nobody reads any more
/// (a broken pipe) is not a reason to stop: a batch is run for its requests,
/// and its log is a by-product. So that is remembered, what follows is
/// dropped, and the run goes on to exit by how its requests went.
///
/// Any other failure (a full disk under `> log`) is one: it is said on
/// stderr and the run ends with exit 1, since what was asked for is not
/// where it was to go.
struct Out;

impl Out {
    fn put(buf: Option<&[u8]>) {
        if STDOUT_CLOSED.load(Ordering::Relaxed) {
            return;
        }
        if let Err(e) = write_through(&mut io::stdout().lock(), buf) {
            STDOUT_CLOSED.store(true, Ordering::Relaxed);
            if e.kind() != io::ErrorKind::BrokenPipe {
                let _ = writeln!(ErrOut, "Error writing to stdout: {}", e);
                exit_process(1);
            }
        }
    }
}

impl Write for Out {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        Out::put(Some(buf));
        Ok(buf.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        Out::put(None);
        Ok(())
    }
}

/// `print!` to a stdout that may have closed. See `Out`.
macro_rules! out {
    ($($arg:tt)*) => {{
        let _ = write!(Out, $($arg)*);
    }};
}

/// `println!` to a stdout that may have closed. See `Out`.
macro_rules! outln {
    () => {{
        let _ = writeln!(Out);
    }};
    ($($arg:tt)*) => {{
        let _ = writeln!(Out, $($arg)*);
    }};
}

/// Set once a write to stderr has failed. See `STDOUT_CLOSED`.
static STDERR_CLOSED: AtomicBool = AtomicBool::new(false);

/// Stderr for everything the client says there: in `-a` mode that is the
/// status line of every request. Like `Out`, a reader that has gone away
/// (`api -a seed.api 2>&1 | head -1`) does not stop the batch, where
/// `eprintln!` would panic on the first line nobody took. A stderr that
/// fails in any other way has nowhere left to say so: the run ends, exit 1.
struct ErrOut;

impl ErrOut {
    fn put(buf: Option<&[u8]>) {
        if STDERR_CLOSED.load(Ordering::Relaxed) {
            return;
        }
        if let Err(e) = write_through(&mut io::stderr().lock(), buf) {
            STDERR_CLOSED.store(true, Ordering::Relaxed);
            if e.kind() != io::ErrorKind::BrokenPipe {
                exit_process(1);
            }
        }
    }
}

impl Write for ErrOut {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        ErrOut::put(Some(buf));
        Ok(buf.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        ErrOut::put(None);
        Ok(())
    }
}

/// `eprint!` to a stderr that may have closed. See `ErrOut`.
macro_rules! err {
    ($($arg:tt)*) => {{
        let _ = write!(ErrOut, $($arg)*);
    }};
}

/// `eprintln!` to a stderr that may have closed. See `ErrOut`.
macro_rules! errln {
    () => {{
        let _ = writeln!(ErrOut);
    }};
    ($($arg:tt)*) => {{
        let _ = writeln!(ErrOut, $($arg)*);
    }};
}

/// Whether the prompt turned bracketed paste on, and whether it pushed the
/// kitty keyboard flags: what `restore_terminal` has to undo.
static BRACKETED_PASTE_ON: AtomicBool = AtomicBool::new(false);
static KEYBOARD_FLAGS_PUSHED: AtomicBool = AtomicBool::new(false);

/// Put the terminal back the way the shell had it: keyboard flags popped,
/// bracketed paste off, cursor shown, raw mode off. Each part is undone only
/// if it was done, so this is safe to call from anywhere, any number of
/// times, and does nothing in a run that never touched the terminal.
fn restore_terminal() {
    let modes = leave_prompt_modes();
    let raw = terminal::is_raw_mode_enabled().unwrap_or(false);
    if !(modes || raw) {
        return;
    }
    // Wrapping too: a frame is drawn with it off, and a panic or a signal
    // in the middle of one would leave the shell without it.
    let _ = execute!(io::stdout(), Print("\x1b[?7h"), cursor::Show);
    let _ = terminal::disable_raw_mode();
}

/// Pop the keyboard flags and turn bracketed paste off, each only if the
/// prompt turned it on and it has not been undone yet. Says whether there
/// was anything to undo.
fn leave_prompt_modes() -> bool {
    let keyboard = KEYBOARD_FLAGS_PUSHED.swap(false, Ordering::SeqCst);
    let paste = BRACKETED_PASTE_ON.swap(false, Ordering::SeqCst);
    let mut stdout = io::stdout();
    if keyboard {
        let _ = execute!(stdout, PopKeyboardEnhancementFlags);
    }
    if paste {
        let _ = execute!(stdout, DisableBracketedPaste);
    }
    keyboard || paste
}

/// Restores the terminal when it goes out of scope, so every way out of the
/// prompt does: a normal return, an error passed up with `?`, a panic.
struct TerminalGuard;

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        restore_terminal();
    }
}

/// The responses of a batch that had masked data left out of their export.
static MASKED_RESPONSES: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// The last line of a batch in which an export left masked data out, so
/// that the warning under one request is not lost in a long log.
fn masked_total_line(responses: usize) -> Option<String> {
    let had = match responses {
        0 => return None,
        1 => "1 response had".to_string(),
        n => format!("{} responses had", n),
    };
    Some(format!("warning: {} masked data left out of the export; read those members out with ~just or ~without", had))
}

/// Say `masked_total_line` for the batch that is ending, once.
fn say_masked_total() {
    let responses = MASKED_RESPONSES.swap(0, std::sync::atomic::Ordering::Relaxed);
    if let Some(line) = masked_total_line(responses) {
        errln!("{}", line);
    }
}

/// End the process, with the terminal restored first. `std::process::exit`
/// runs no destructors, so an exit from inside the prompt would otherwise
/// leave the shell in raw mode with bracketed paste on.
fn exit_process(code: i32) -> ! {
    restore_terminal();
    // A batch that ends here ends with its closing line all the same.
    say_masked_total();
    // What is still buffered goes out as everything else did. A stdout that
    // has failed is not tried again (and does not lead back here).
    let _ = Out.flush();
    release_clipboard();
    std::process::exit(code)
}

/// The system clipboard, once something has been copied to it, kept until
/// the process ends. On Linux what is copied is held by the program that
/// copied it and handed out when another asks: under X11 it is gone when
/// the clipboard is let go of, so a session keeps hold of it for as long as
/// it runs.
fn held_clipboard() -> std::sync::MutexGuard<'static, Option<arboard::Clipboard>> {
    static HELD: std::sync::Mutex<Option<arboard::Clipboard>> = std::sync::Mutex::new(None);
    HELD.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// Put `text` on the system clipboard: `> clipboard` and ctrl+y.
fn copy_to_clipboard(text: &str) -> Result<(), String> {
    let mut held = held_clipboard();
    if held.is_none() {
        *held = Some(arboard::Clipboard::new().map_err(|e| e.to_string())?);
    }
    held.as_mut().expect("just made").set_text(text).map_err(|e| e.to_string())
}

/// Let go of the clipboard as the process ends. Under X11 that is when what
/// was copied is handed to the desktop's clipboard manager, which keeps it
/// for a paste that comes after this process is gone: `exit` runs no
/// destructors, so it is done by hand. Elsewhere there is nothing to hand
/// over: macOS and Windows keep what is copied themselves.
fn release_clipboard() {
    held_clipboard().take();
}

/// A panic prints its message through the default hook; before that, the
/// terminal is restored so the message is readable and the shell usable.
///
/// Only for a panic on the thread that installs the hook, which is the one
/// the prompt runs on. A panic on a background loader thread ends that
/// thread alone: the prompt goes on, and still needs its terminal modes.
fn install_panic_hook() {
    let default_hook = std::panic::take_hook();
    let owner = thread::current().id();
    std::panic::set_hook(Box::new(move |info| {
        if thread::current().id() == owner {
            restore_terminal();
        }
        default_hook(info);
    }));
}

