    #[test]
    fn a_save_under_an_override_leaves_the_stored_connection() {
        // No override: a new name renames the session's connection.
        assert_eq!(save_replaces("staging", "mine", false), Some("staging".to_string()));
        assert_eq!(save_replaces("staging", "staging", false), Some("staging".to_string()));
        // An override: a new name is a new connection, the same name is not.
        assert_eq!(save_replaces("staging", "mine", true), None);
        assert_eq!(save_replaces("staging", "staging", true), Some("staging".to_string()));
        // A session with no saved connection replaces nothing.
        assert_eq!(save_replaces("", "mine", false), None);
        assert_eq!(save_replaces("", "mine", true), None);

        let saved = ["a".to_string(), "x".to_string()];
        assert!(save_asks_to_overwrite(&saved, "x", "a"));
        assert!(!save_asks_to_overwrite(&saved, "a", "a"));
        assert!(!save_asks_to_overwrite(&saved, "new", "a"));
    }

    /// A body that hands out `good` and then fails.
    struct Breaks<'a> {
        good: &'a [u8],
    }

    impl IoRead for Breaks<'_> {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            if self.good.is_empty() {
                return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "connection reset"));
            }
            let n = self.good.len().min(buf.len());
            buf[..n].copy_from_slice(&self.good[..n]);
            self.good = &self.good[n..];
            Ok(n)
        }
    }

    /// Somewhere that can't be written to: a full disk.
    struct Full;

    impl Write for Full {
        fn write(&mut self, _: &[u8]) -> io::Result<usize> {
            Err(io::Error::new(io::ErrorKind::StorageFull, "No space left on device"))
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    #[test]
    fn a_stream_tells_a_body_that_broke_off_from_a_write_that_failed() {
        assert!(matches!(stream_to_sink(Breaks { good: b"[1," }, &mut Vec::new()), Err(StreamFailure::Body(_))));
        assert!(matches!(stream_to_sink(&b"[1,2]"[..], &mut Full), Err(StreamFailure::Write(_))));
    }

    #[test]
    fn a_streamed_outfile_takes_its_name_when_the_body_has_ended() {
        let dir = tempfile::tempdir().unwrap();
        let d = dir.path();
        let target = d.join("out.json");
        let path = target.to_str().unwrap();

        let body = stream_to_outfile(&b"[1,2]"[..], path).unwrap();
        assert_eq!((body.bytes, fs::read_to_string(&target).unwrap()), (5, "[1,2]".to_string()));
        assert_eq!(names_in(d), ["out.json"]);

        // A body that breaks off leaves the target as it was, and nothing else.
        let broken = stream_to_outfile(Breaks { good: b"[9," }, path);
        assert!(matches!(broken, Err(StreamFailure::Body(_))));
        assert_eq!(fs::read_to_string(&target).unwrap(), "[1,2]");
        assert_eq!(names_in(d), ["out.json"]);

        // A directory that is not there is a local failure.
        let nowhere = d.join("nodir/out.json");
        assert!(matches!(stream_to_outfile(&b"[1]"[..], nowhere.to_str().unwrap()), Err(StreamFailure::Write(_))));
        // So is a target that is a directory.
        assert!(matches!(stream_to_outfile(&b"[1]"[..], d.to_str().unwrap()), Err(StreamFailure::Write(_))));

        // A file that happens to have the temporary name is the user's: it
        // is neither written over nor removed, whether the stream ends well
        // or not.
        let theirs = [d.join("out.json.part"), d.join(format!("out.json.{}.part", std::process::id()))];
        for file in &theirs {
            fs::write(file, "mine").unwrap();
        }
        stream_to_outfile(&b"[3]"[..], path).unwrap();
        assert!(stream_to_outfile(Breaks { good: b"[4," }, path).is_err());
        assert_eq!(fs::read_to_string(&target).unwrap(), "[3]");
        for file in &theirs {
            assert_eq!(fs::read_to_string(file).unwrap(), "mine");
        }
        assert_eq!(names_in(d).len(), 3);

        // A target that can't be renamed over gets the finished bytes.
        let refuse = |_: &std::path::Path, _: &std::path::Path| Err(io::Error::from(io::ErrorKind::ResourceBusy));
        stream_to_outfile_with(&b"[5]"[..], path, &Arc::new(AtomicBool::new(false)), refuse).unwrap();
        assert_eq!(fs::read_to_string(&target).unwrap(), "[5]");
        assert_eq!(names_in(d).len(), 3);
    }

    /// A body whose transfer is given up once its first piece has been read.
    struct GivenUpMidway<'a> {
        pieces: Vec<&'static [u8]>,
        given_up: &'a AtomicBool,
    }

    impl IoRead for GivenUpMidway<'_> {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            if self.pieces.is_empty() {
                return Ok(0);
            }
            let piece = self.pieces.remove(0);
            buf[..piece.len()].copy_from_slice(piece);
            self.given_up.store(true, Ordering::SeqCst);
            Ok(piece.len())
        }
    }

    #[test]
    fn a_transfer_that_is_given_up_leaves_the_target_as_it_was() {
        let dir = tempfile::tempdir().unwrap();
        let d = dir.path();
        let target = d.join("out.json");
        let path = target.to_str().unwrap();
        let rename = |from: &std::path::Path, to: &std::path::Path| fs::rename(from, to);
        fs::write(&target, "before").unwrap();

        // Given up before it began: nothing is made.
        let given_up = Arc::new(AtomicBool::new(true));
        assert!(matches!(stream_to_outfile_with(&b"[1]"[..], path, &given_up, rename), Err(StreamFailure::Body(_))));
        assert_eq!((names_in(d), fs::read_to_string(&target).unwrap()), (vec!["out.json".to_string()], "before".to_string()));

        // Given up partway: the rest is not read, and nothing takes the
        // target's place, also when the body would have ended there.
        for pieces in [vec![&b"[1,"[..], &b"2]"[..]], vec![&b"[1,2]"[..]]] {
            let given_up = Arc::new(AtomicBool::new(false));
            let body = GivenUpMidway { pieces, given_up: &given_up };
            assert!(matches!(stream_to_outfile_with(body, path, &given_up, rename), Err(StreamFailure::Body(_))));
            assert_eq!((names_in(d), fs::read_to_string(&target).unwrap()), (vec!["out.json".to_string()], "before".to_string()));
        }
        // Nothing of it is still listed as under way.
        assert!(live_parts().iter().all(|(part, _)| !part.starts_with(d)));
    }

    #[cfg(unix)]
    #[test]
    fn a_streamed_outfile_keeps_what_the_target_is() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempfile::tempdir().unwrap();
        let d = dir.path();

        // Not a regular file: written as it stands.
        assert_eq!(stream_to_outfile(&b"[1,2]"[..], "/dev/null").unwrap().bytes, 5);

        // A link stays a link, and the file it names gets the body.
        fs::write(d.join("real.json"), "old").unwrap();
        std::os::unix::fs::symlink("real.json", d.join("link.json")).unwrap();
        stream_to_outfile(&b"[1]"[..], d.join("link.json").to_str().unwrap()).unwrap();
        assert!(fs::symlink_metadata(d.join("link.json")).unwrap().file_type().is_symlink());
        assert_eq!(fs::read_to_string(d.join("real.json")).unwrap(), "[1]");

        // A link to nothing creates the file it points at.
        std::os::unix::fs::symlink(d.join("later.json"), d.join("dangling.json")).unwrap();
        stream_to_outfile(&b"[2]"[..], d.join("dangling.json").to_str().unwrap()).unwrap();
        assert!(fs::symlink_metadata(d.join("dangling.json")).unwrap().file_type().is_symlink());
        assert_eq!(fs::read_to_string(d.join("later.json")).unwrap(), "[2]");
        assert_eq!(names_in(d), ["dangling.json", "later.json", "link.json", "real.json"]);

        // A file made private stays private.
        let private = d.join("private.json");
        fs::write(&private, "old").unwrap();
        fs::set_permissions(&private, fs::Permissions::from_mode(0o600)).unwrap();
        stream_to_outfile(&b"[3]"[..], private.to_str().unwrap()).unwrap();
        assert_eq!(fs::metadata(&private).unwrap().permissions().mode() & 0o777, 0o600);
        assert_eq!(fs::read_to_string(&private).unwrap(), "[3]");

        // A file that can be written, in a directory that can't.
        let locked = d.join("locked");
        fs::create_dir(&locked).unwrap();
        fs::write(locked.join("keep.json"), "old").unwrap();
        fs::set_permissions(&locked, fs::Permissions::from_mode(0o555)).unwrap();
        let written = stream_to_outfile(&b"[4]"[..], locked.join("keep.json").to_str().unwrap());
        let created = stream_to_outfile(&b"[4]"[..], locked.join("new.json").to_str().unwrap());
        fs::set_permissions(&locked, fs::Permissions::from_mode(0o755)).unwrap();
        written.unwrap();
        assert!(matches!(created, Err(StreamFailure::Write(_))));
        assert_eq!(fs::read_to_string(locked.join("keep.json")).unwrap(), "[4]");
        assert_eq!(names_in(&locked), ["keep.json"]);
    }

    #[test]
    fn saving_under_a_new_name_renames_and_keeps_the_default() {
        let connection = |name: &str, credential: &str| SavedConnection {
            name: name.to_string(),
            url: "http://x".to_string(),
            auth_type: "key".to_string(),
            credential: credential.to_string(),
            client_id: String::new(),
        };
        let names = |data: &KeychainData| data.connections.iter().map(|e| e.name.clone()).collect::<Vec<_>>();
        let mut data = KeychainData::default();
        put_connection(&mut data, &connection("a", "1"), None);
        put_connection(&mut data, &connection("b", "1"), None);
        data.default = "a".to_string();

        // The same name: replaced in place.
        put_connection(&mut data, &connection("a", "2"), Some("a"));
        assert_eq!((names(&data), data.connections[0].credential.as_str(), data.default.as_str()), (vec!["a".to_string(), "b".to_string()], "2", "a"));

        // A new name: the old entry goes and the default follows.
        put_connection(&mut data, &connection("c", "3"), Some("a"));
        assert_eq!((names(&data), data.default.as_str()), (vec!["b".to_string(), "c".to_string()], "c"));

        // Renaming one that was not the default leaves the default alone.
        put_connection(&mut data, &connection("d", "4"), Some("b"));
        assert_eq!((names(&data), data.default.as_str()), (vec!["c".to_string(), "d".to_string()], "c"));

        // Onto a name that exists: that entry is replaced, not doubled.
        put_connection(&mut data, &connection("c", "5"), Some("d"));
        assert_eq!((names(&data), data.connections[0].credential.as_str()), (vec!["c".to_string()], "5"));
    }

    #[test]
    fn history_keeps_an_entry_of_several_lines_as_one() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join(".api_history");
        assert!(load_history_from(&path).is_empty());

        let body = "PUT /x {\n  \"a\": \"C:\\\\dir\\n\",\n  \"b\": 1\n}";
        append_history_to(&path, "GET /a");
        append_history_to(&path, body);
        append_history_to(&path, "GET /b");
        // One line per entry in the file…
        assert_eq!(fs::read_to_string(&path).unwrap().lines().count(), 3);
        // …and the entries come back as they were typed, backslashes and all.
        assert_eq!(load_history_from(&path), ["GET /a", body, "GET /b"]);

        // A file from before: every line is an entry, read as it is.
        let old = "GET /a\nPUT /x {\"s\":\"a\\nb \\\\ c\"}\n\nGET /c\n";
        fs::write(&path, old).unwrap();
        assert_eq!(load_history_from(&path), ["GET /a", "PUT /x {\"s\":\"a\\nb \\\\ c\"}", "GET /c"]);

        // Line breaks as a paste or a Windows file has them are line breaks
        // too: each is one entry on one line, read back with `\n`.
        fs::remove_file(&path).unwrap();
        append_history_to(&path, "PUT /x {\r\n  \"a\": 1\r\n}");
        append_history_to(&path, "PUT /y {\r  \"b\": 2\r}");
        assert_eq!(fs::read_to_string(&path).unwrap().lines().count(), 2);
        assert!(!fs::read_to_string(&path).unwrap().contains('\r'));
        assert_eq!(load_history_from(&path), ["PUT /x {\n  \"a\": 1\n}", "PUT /y {\n  \"b\": 2\n}"]);

        // The character that stands for a line break is read as one, also
        // where an entry held it itself. That is the price of one line per
        // entry, and it is paid only in the history: the request was sent
        // as it was typed.
        fs::remove_file(&path).unwrap();
        append_history_to(&path, "PUT /z {\"s\":\"a\u{2424}b\"}");
        assert_eq!(load_history_from(&path), ["PUT /z {\"s\":\"a\nb\"}"]);
        assert_eq!(history_entry(&history_line("a\nb\r\nc\rd")), "a\nb\nc\nd");
    }

    #[test]
    fn history_is_capped_and_private() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join(".api_history");
        let lines: String = (0..HISTORY_LIMIT + 250).map(|i| format!("GET /{i}\n")).collect();
        fs::write(&path, lines).unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&path, fs::Permissions::from_mode(0o644)).unwrap();
        }

        // Loading keeps the last 1000 and rewrites the file to match.
        let loaded = load_history_from(&path);
        assert_eq!(loaded.len(), HISTORY_LIMIT);
        assert_eq!((loaded[0].as_str(), loaded.last().unwrap().as_str()), ("GET /250", "GET /1249"));
        assert_eq!(fs::read_to_string(&path).unwrap().lines().count(), HISTORY_LIMIT);
        // A file within the limit is left as it is.
        let before = fs::read_to_string(&path).unwrap();
        load_history_from(&path);
        assert_eq!(fs::read_to_string(&path).unwrap(), before);

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = |p: &std::path::Path| fs::metadata(p).unwrap().permissions().mode() & 0o777;
            assert_eq!(mode(&path), 0o600, "an existing file is made private");
            let fresh = dir.path().join("fresh");
            append_history_to(&fresh, "GET /a");
            assert_eq!(mode(&fresh), 0o600, "a new file is created private");
            // A world-readable file within the limit is made private too.
            fs::set_permissions(&fresh, fs::Permissions::from_mode(0o644)).unwrap();
            load_history_from(&fresh);
            assert_eq!(mode(&fresh), 0o600);
        }
        // Nothing is left beside it.
        assert!(fs::read_dir(dir.path()).unwrap().all(|e| !e.unwrap().file_name().to_string_lossy().contains(".tmp-")));
    }

    #[cfg(unix)]
    #[test]
    fn a_history_trim_writes_through_a_link_and_into_a_file_of_its_own() {
        let dir = tempfile::tempdir().unwrap();
        let d = dir.path();
        let lines: String = (0..HISTORY_LIMIT + 5).map(|i| format!("GET /{i}\n")).collect();

        // A history kept elsewhere (a dotfiles checkout) stays there.
        fs::create_dir(d.join("dotfiles")).unwrap();
        let real = d.join("dotfiles/history");
        let link = d.join(".api_history");
        fs::write(&real, &lines).unwrap();
        std::os::unix::fs::symlink("dotfiles/history", &link).unwrap();
        assert_eq!(load_history_from(&link).len(), HISTORY_LIMIT);
        assert!(fs::symlink_metadata(&link).unwrap().file_type().is_symlink());
        assert_eq!(fs::read_to_string(&real).unwrap().lines().count(), HISTORY_LIMIT);
        assert_eq!(names_in(&d.join("dotfiles")), ["history"]);

        // Something that already has the temporary name is not written to,
        // and not through: the history is no worse off untrimmed.
        let plain = d.join("plain");
        fs::write(&plain, &lines).unwrap();
        let planted = d.join(format!("plain.tmp-{}", std::process::id()));
        fs::write(d.join("victim"), "theirs").unwrap();
        std::os::unix::fs::symlink("victim", &planted).unwrap();
        load_history_from(&plain);
        assert_eq!(fs::read_to_string(d.join("victim")).unwrap(), "theirs");
        assert!(fs::symlink_metadata(&planted).unwrap().file_type().is_symlink());
        assert!(fs::symlink_metadata(&plain).unwrap().file_type().is_file());
        fs::remove_file(&planted).unwrap();

        // A trim that can't take the file's place leaves nothing beside it.
        let refuse = |_: &std::path::Path, _: &std::path::Path| Err(io::Error::from(io::ErrorKind::ResourceBusy));
        let entries: Vec<String> = lines.lines().map(String::from).collect();
        save_history_with(&plain, &entries, refuse);
        assert_eq!(fs::read_to_string(&plain).unwrap(), lines);
        assert_eq!(names_in(d), [".api_history", "dotfiles", "plain", "victim"]);
    }

    #[test]
    fn a_partial_file_gets_a_name_nothing_has() {
        let dir = tempfile::tempdir().unwrap();
        let d = dir.path();
        let target = d.join("out.json");
        let pid = std::process::id();

        let (first, _) = create_part(&target).unwrap();
        assert_eq!(first, d.join(format!("out.json.{pid}.part")));
        // That name is taken now, by a file with something in it.
        fs::write(&first, "theirs").unwrap();
        let (second, mut file) = create_part(&target).unwrap();
        assert_eq!(second, d.join(format!("out.json.{pid}-1.part")));
        file.write_all(b"mine").unwrap();
        assert_eq!(fs::read_to_string(&first).unwrap(), "theirs");
        assert_eq!(fs::read_to_string(&second).unwrap(), "mine");

        // With every name taken there is none to give, and none is written over.
        for n in 2..8 {
            fs::write(d.join(format!("out.json.{pid}-{n}.part")), "theirs").unwrap();
        }
        assert_eq!(create_part(&target).unwrap_err().kind(), io::ErrorKind::AlreadyExists);
        assert_eq!(fs::read_to_string(&second).unwrap(), "mine");
        assert_eq!(names_in(d).len(), 8);
    }

    #[test]
    fn a_curl_command_quotes_every_value_for_the_shell() {
        assert_eq!(sh_quote("plain"), "'plain'");
        assert_eq!(sh_quote("O'Brien"), r#"'O'\''Brien'"#);
        assert_eq!(sh_quote("$HOME `id` \"x\""), "'$HOME `id` \"x\"'");

        let mut state = AppState::new(Config {
            base_uri: "http://localhost:5000".to_string(),
            api_key: "k".to_string(),
            ..Config::default()
        });
        assert_eq!(build_curl(&state), None, "nothing was sent yet");

        // A body with an apostrophe, a URI with `$` and a backtick. The
        // backtick is in the URL as the request had it, encoded.
        state.prev_method = "PUT".to_string();
        state.prev_uri = "/people~where(name=$USER`id`)".to_string();
        state.prev_body = r#"{"name":"O'Brien"}"#.to_string();
        assert_eq!(
            build_curl(&state).unwrap(),
            concat!(
                "curl -gfsSL -X PUT 'http://localhost:5000/api/v1/people~where(name=$USER%60id%60)'",
                " -H 'Authorization: Basic Oms='",
                " -H 'Accept: application/json'",
                " -H 'Content-Type: application/json'",
                r#" --data-binary '{"name":"O'\''Brien"}'"#,
            )
        );

        // A key shaped like a JWT went out as Bearer, and so does the command.
        let jwt = format!("ey{}", "a".repeat(200));
        state.config.api_key = jwt.clone();
        state.prev_method = "GET".to_string();
        state.prev_uri = "/people".to_string();
        state.prev_body.clear();
        assert_eq!(
            build_curl(&state).unwrap(),
            format!("curl -gfsSL -X GET 'http://localhost:5000/api/v1/people' -H 'Authorization: Bearer {jwt}' -H 'Accept: application/json'")
        );
        state.config.api_key.clear();
        state.config.token = "tok".to_string();
        assert!(build_curl(&state).unwrap().contains(" -H 'Authorization: Bearer tok' "));

        // Outfiles: `>` is -o, `>>` is the shell's, the clipboard is neither.
        let tail = |state: &AppState| build_curl(state).unwrap().split(" -H 'Accept: ").nth(1).unwrap().to_string();
        state.prev_outfile = "it's.CSV".to_string();
        state.prev_display_outfile = "it's.CSV".to_string();
        assert_eq!(tail(&state), r#"text/csv' -o 'it'\''s.CSV'"#);
        state.prev_outfile_append = true;
        assert_eq!(tail(&state), r#"text/csv' >> 'it'\''s.CSV'"#);
        state.prev_outfile = "clipboard".to_string();
        state.prev_display_outfile = "Clipboard".to_string();
        state.prev_outfile_append = false;
        assert_eq!(tail(&state), "application/json'");

        // A file body with `~map()`.
        state.prev_outfile.clear();
        state.prev_display_outfile.clear();
        state.prev_method = "PUT".to_string();
        state.prev_body = "@data's.csv~map(com.heads.t)".to_string();
        assert_eq!(
            tail(&state),
            r#"application/json' -H 'Content-Type: text/csv' -H 'X-Request-Map: com.heads.t' --data-binary '@data'\''s.csv'"#
        );
        // An NDJSON file body, and one under the home directory.
        state.prev_body = "@events.NDJSON".to_string();
        assert_eq!(
            tail(&state),
            "application/x-ndjson' -H 'Content-Type: application/x-ndjson' --data-binary '@events.NDJSON'"
        );
        state.prev_body = "@~/seeds/a.json".to_string();
        assert!(tail(&state).ends_with(&format!(" --data-binary '@{}'", expand_home("~/seeds/a.json"))), "{}", tail(&state));

        // A glob body is several files combined: no curl command sends that.
        for glob in ["@people/*.json", "@people/a?.json~map(com.heads.t)", "@events/[ab].ndjson"] {
            state.prev_body = glob.to_string();
            assert_eq!(curl_refusal(&state), Some("a glob body can't be written as a curl command"), "{glob}");
            assert_eq!(build_curl(&state), None, "{glob}");
        }
        state.prev_body = r#"{"pattern":"@a/*.json"}"#.to_string();
        assert_eq!(curl_refusal(&state), None);

        // Streaming is in the headers when the request was streamed, which
        // it is not under export. `-i` and `--ndjson` are there as sent.
        // They are read when the request is sent, and are that request's:
        // a setting changed since (in the menu, or by a file's `set` lines
        // ending with the file) is not in the command.
        let sent_under = |state: &mut AppState, change: &dyn Fn(&mut Config)| {
            state.method = "GET".to_string();
            state.uri = "/x".to_string();
            state.body.clear();
            let before = state.config.clone();
            change(&mut state.config);
            record_last_request(state);
            state.config = before;
            build_curl(state).unwrap().split(" -H 'Accept: ").nth(1).unwrap().to_string()
        };
        assert_eq!(sent_under(&mut state, &|c| c.streaming = true), "application/json;stream=true'");
        assert_eq!(
            sent_under(&mut state, &|c| {
                c.streaming = true;
                c.export_id = Some("com.heads.seedID".to_string());
            }),
            "application/json'"
        );
        assert_eq!(sent_under(&mut state, &|c| c.include_nulls = true), "application/json;skipNulls=false'");
        assert_eq!(sent_under(&mut state, &|c| c.ndjson = true), "application/x-ndjson'");
        assert_eq!(sent_under(&mut state, &|_| ()), "application/json'");
        // Turned on after the request was sent: not what was sent.
        state.config.include_nulls = true;
        state.config.ndjson = true;
        state.config.streaming = true;
        assert_eq!(tail(&state), "application/json'");
    }

    #[test]
    fn a_spec_that_leaves_things_out_is_still_a_spec() {
        // An operation without `responses`, a tag without a name, components
        // without schemas: none of them makes the spec unreadable.
        let spec: ApiSpec = serde_json::from_str(
            r#"{
                "paths": {
                    "/people": { "get": { "tags": ["people"] }, "put": { "responses": {} } },
                    "/things": {}
                },
                "components": {},
                "tags": [{ "x-type": "person" }, { "name": "people" }]
            }"#,
        )
        .unwrap();
        let mut paths: Vec<&String> = spec.paths.keys().collect();
        paths.sort();
        assert_eq!(paths, ["/people", "/things"]);
        assert!(spec.components.unwrap().schemas.is_empty());
        // No paths at all is an empty spec, not an error.
        assert!(serde_json::from_str::<ApiSpec>("{}").unwrap().paths.is_empty());
        // What is not a spec still is not one.
        assert!(serde_json::from_str::<ApiSpec>("[1]").is_err());
    }

    #[test]
    fn paths_are_read_with_either_separator_where_both_separate() {
        // `~/` everywhere; `~\` only where `\` is a separator.
        assert_eq!(home_relative("~/seeds/a.api", false), Some("seeds/a.api"));
        assert_eq!(home_relative("~/seeds/a.api", true), Some("seeds/a.api"));
        assert_eq!(home_relative(r"~\seeds\a.api", true), Some(r"seeds\a.api"));
        assert_eq!(home_relative(r"~\seeds\a.api", false), None);
        for other in ["seeds/a.api", "/tmp/~/a", "~user/a", "~"] {
            assert_eq!(home_relative(other, true), None, "{other}");
        }
        // On this platform `~/x` is in the home directory, and nothing else is.
        let home = dirs::home_dir().unwrap();
        assert_eq!(expand_home("~/x.json"), home.join("x.json").to_string_lossy());
        assert_eq!(expand_home("x.json"), "x.json");
        assert_eq!(expand_home("/tmp/x.json"), "/tmp/x.json");

        // An alias include.
        assert_eq!(split_alias("cl/sv.api", false), Some(("cl", "sv.api")));
        assert_eq!(split_alias("cl/seeds/sv.api", true), Some(("cl", "seeds/sv.api")));
        assert_eq!(split_alias(r"cl\sv.api", true), Some(("cl", "sv.api")));
        assert_eq!(split_alias(r"cl\sv.api", false), None);
        assert_eq!(split_alias("sv.api", true), None);
    }

