    #[test]
    fn a_map_ghost_is_of_the_name_tab_writes() {
        // One name is the start of another: typed whole, it is the one Tab
        // takes, and the ghost is its `)`, not the end of the longer name.
        for line in ["PUT /x @a.csv~map(com.heads.csv", "GET /about && PUT /x @a.csv~map(com.heads.csv", "PUT /x @a.csv~map(", "PUT /x @a.csv~map(com.heads.s"] {
            let mut state = completing(line);
            state.mapped_types = strings(&["com.heads.csv", "com.heads.csv-product", "com.heads.sql"]);
            let before = state.input[..char_to_byte_idx(&state.input, state.cursor_pos)].to_string();
            let ghost = render_input_content(&mut state, 200).2;
            assert!(!ghost.is_empty(), "{line}");
            tab_pressed(&mut state);
            assert!(shown(&state).starts_with(&format!("{before}{ghost}^")), "{line}: ghost {ghost:?}, Tab wrote {}", shown(&state));
        }
        let mut state = completing("PUT /x @a.csv~map(com.heads.csv");
        state.mapped_types = strings(&["com.heads.csv", "com.heads.csv-product", "com.heads.sql"]);
        assert_eq!(render_input_content(&mut state, 200).2, ")");
    }

    #[test]
    fn behind_a_blank_after_a_file_path_nothing_is_completed() {
        let dir = tempfile::tempdir().unwrap();
        fs::write(dir.path().join("seed.api"), "").unwrap();
        let base = dir.path().display().to_string();
        for line in [
            "GET /x > clip ^".to_string(),
            "GET /x > ~ ^".to_string(),
            "GET /x >> clip  ^".to_string(),
            "PUT /x @a.csv~ ^".to_string(),
            "PUT /x @a.csv~ma ^".to_string(),
            format!("PUT /x @{base}/se ^"),
            "GET /x > clip ^ && GET /about".to_string(),
        ] {
            for experimental in [false, true] {
                let (ghost, after) = ghost_then_tab(&line, experimental);
                assert_eq!((ghost.as_str(), after.as_str()), ("", line.as_str()));
                let mut state = completing(&line);
                assert!(!backtab_pressed(&mut state));
                assert_eq!(shown(&state), line);
            }
        }
        // At the end of the path itself both still agree.
        assert_eq!(ghost_then_tab("GET /x > clip^", false), ("board".to_string(), "GET /x > clipboard^".to_string()));
        assert_eq!(ghost_then_tab("PUT /x @a.csv~^", false), ("map(".to_string(), "PUT /x @a.csv~map(^".to_string()));
    }

    #[test]
    fn set_is_a_keyword_and_no_start_of_a_path() {
        for typed in ["s", "se", "set", "SET"] {
            assert!(could_become_a_keyword(typed), "{typed}");
        }
        assert!(!could_become_a_keyword("sets"));
        // The line of a directive is not an include to complete.
        for line in ["set export com.heads.seedID", "set include-nulls off", "set ", "set in"] {
            assert!(include_path_context(line, 0, line.len()).is_none_or(|ctx| !ctx.is_include), "{line}");
        }
        // `export` is a path like any other now.
        assert!(include_path_context("export", 0, 6).is_some_and(|ctx| ctx.is_include));
    }

    #[test]
    fn tab_completes_the_name_on_a_set_line() {
        assert_eq!(ghost_then_tab("set in^", false), ("clude-nulls".to_string(), "set include-nulls^".to_string()));
        assert_eq!(ghost_then_tab("set f^", false), ("ail-fast".to_string(), "set fail-fast^".to_string()));
        assert_eq!(ghost_then_tab("SET t^", false), ("imeout".to_string(), "SET timeout^".to_string()));
        // Nothing typed: the first of the list, and Tab goes through them.
        let mut state = completing("set ^");
        let mut seen = Vec::new();
        for _ in 0..SETTING_NAMES.len() + 1 {
            assert!(tab_pressed(&mut state));
            seen.push(shown(&state));
        }
        let all: Vec<String> = SETTING_NAMES.iter().chain(SETTING_NAMES.first()).map(|name| format!("set {name}^")).collect();
        assert_eq!(seen, all);
        assert!(backtab_pressed(&mut state));
        assert_eq!(shown(&state), format!("set {}^", SETTING_NAMES.last().unwrap()));
        // Nothing to add to a name that is no setting, behind a value, or
        // behind `set` with no blank yet.
        for line in ["set nulls^", "set IN^", "set timeout 3^", "set export off^", "set include-nulls ^"] {
            let (ghost, after) = ghost_then_tab(line, false);
            assert_eq!((ghost.as_str(), after.as_str()), ("", line), "{line}");
        }
        assert_eq!(ghost_then_tab("set^", false).0, "");
    }

    #[test]
    fn a_key_ghost_in_a_chain_is_of_the_segment_the_cursor_is_in() {
        // As the key handler reads it while a key is typed in its quotes.
        let typed = |marked: &str| {
            let mut state = completing_body(marked);
            with_chain_segment_view(&mut state, |state| {
                if json_context_at_cursor(state).is_some_and(|ctx| ctx.pos == JsonPos::Key && ctx.in_string) {
                    handle_json_tab_completion(state, false, false);
                }
            });
            state
        };
        // `givenName` is a key of a person, not of what `/settings` takes.
        let mut state = typed("GET /people && PUT /settings {\"g^");
        let ghost = render_input_content(&mut state, 200).2;
        assert!(!ghost.contains("ivenName"), "{ghost}");
        let mut state = typed("GET /settings && PUT /people [{\"g^");
        assert_eq!(render_input_content(&mut state, 200).2, "dprForgotten\":");
    }

    #[test]
    fn shift_tab_before_any_tab_writes_nothing_in_a_body() {
        let mut state = completing_body("PUT /people [{\"g^");
        handle_json_tab_completion(&mut state, false, false);
        assert!(!render_input_content(&mut state, 200).2.is_empty(), "a key is offered");
        assert!(!backtab_pressed(&mut state));
        assert_eq!(shown(&state), "PUT /people [{\"g^");
        // Tab still writes what the ghost showed.
        tab_pressed(&mut state);
        assert_eq!(shown(&state), "PUT /people [{\"gdprForgotten\":^");
    }

    #[test]
    fn tab_in_the_middle_of_a_uri_word_writes_nothing() {
        for line in ["GET /pe^ople", "GET /peo^ple/find", "/pe^ople", "GET /about && GET /pe^ople", "GET /people~wh^ere(name=x)"] {
            let mut state = completing(line);
            assert_eq!(render_input_content(&mut state, 200).2, "", "{line}");
            tab_pressed(&mut state);
            assert_eq!(shown(&state), line);
        }
        // In front of what is no part of the word it completes, and what
        // follows is kept.
        assert_eq!(tabbed("GET /pe^~take(5)"), "GET /people^~take(5)");
        assert_eq!(tabbed("GET /pe^/find"), "GET /people^/find");
    }

    #[test]
    fn an_archive_redirect_onto_this_machine_is_only_for_a_download_from_it() {
        let url = |text: &str| reqwest::Url::parse(text).unwrap();
        let refusal = |asked: &str, to: &str| archive_redirect_refusal(Some(&url(asked)), &url(to), 1);
        // A release is served from another host, over https.
        assert_eq!(refusal("https://github.com/a/b/archive/1.tar.gz", "https://codeload.github.com/a/b/tar.gz/1"), None);
        assert_eq!(refusal("http://127.0.0.1:5000/moved", "http://127.0.0.1:5000/lib.tar.gz"), None);
        assert_eq!(refusal("http://localhost:5000/moved", "https://example.com/lib.tar.gz"), None);
        // A server elsewhere does not send the client to what listens here.
        for here in ["http://127.0.0.1:8080/x.tar.gz", "https://localhost/x.tar.gz", "http://[::1]:9/x"] {
            assert_eq!(refusal("https://example.com/r", here), Some("redirected to this machine"), "{here}");
        }
        assert_eq!(refusal("https://example.com/r", "http://example.com/r"), Some("redirected to a url that is not https"));
        assert_eq!(refusal("http://127.0.0.1:5000/moved-off", "http://example.com/r"), Some("redirected to a url that is not https"));
        assert_eq!(archive_redirect_refusal(Some(&url("https://a.example/r")), &url("https://a.example/r"), 11), Some("too many redirects"));
        assert_eq!(archive_redirect_refusal(None, &url("http://127.0.0.1/x"), 1), Some("redirected to this machine"));
    }

    #[test]
    fn a_file_remote_that_is_gone_is_one_in_either_spelling() {
        let dir = tempfile::tempdir().unwrap();
        let there = dir.path().display().to_string();
        assert!(!git_file_remote_is_gone(&format!("file://{there}")));
        assert!(!git_file_remote_is_gone(&format!("file://localhost{there}")));
        assert!(git_file_remote_is_gone(&format!("file://{there}/gone")));
        assert!(git_file_remote_is_gone(&format!("file://localhost{there}/gone")));
        // Not a file of this machine at all: nothing is said about it.
        assert!(!git_file_remote_is_gone("https://example.com/repo"));
        assert!(!git_file_remote_is_gone("file://otherhost/repo"));
    }

    #[test]
    fn a_hard_link_and_a_device_in_a_tar_are_not_unpacked() {
        let dir = tempfile::tempdir().unwrap();
        let bytes = tar_gz(&[("a.api", "GET /a\n")], |builder| {
            let mut link = tar::Header::new_gnu();
            link.set_entry_type(tar::EntryType::Link);
            link.set_size(0);
            builder.append_link(&mut link, "hosts", "/etc/hosts").unwrap();
            for (kind, name) in [(tar::EntryType::Fifo, "pipe"), (tar::EntryType::Char, "tty")] {
                let mut header = tar::Header::new_gnu();
                header.set_entry_type(kind);
                header.set_size(0);
                header.set_mode(0o644);
                header.set_path(name).unwrap();
                header.set_cksum();
                builder.append(&header, io::empty()).unwrap();
            }
        });
        let dest = dir.path().join("out");
        unpack_archive(&bytes, &dest).unwrap();
        assert!(dest.join("a.api").is_file());
        for name in ["hosts", "pipe", "tty"] {
            assert!(fs::symlink_metadata(dest.join(name)).is_err(), "{name} was unpacked");
        }
    }

